"""AI attribution: this whole file was generated by Claude (Anthropic) in Claude Code, following
design decisions made by the author. See ATTRIBUTION.md for details.

Natural-label control as the mean over 8 fixed random starts (approved by the author, 2026-11-20).
Why: the stored single control's presence concordance (0.230) is one draw of a start-dependent quantity (0.264-0.598
over 8 starts; scripts/p1v4_control_seeds_dev.py). train_logreg seeds the batch order but not torch.nn.Linear's init,
and natural labels leave the sound-beyond-label direction unconstrained, so it keeps the random start.

fit: for torch seeds 0-7, the control refitted exactly as scripts/p1v4_grounding.py control_cmd (stored features
     data/p1v4/runs/grounding/control/feats_train_natural.npz, same holdout units, weight decays, 8 epochs, choice by
     holdout log loss, refit on all), with torch.manual_seed(seed) set once before the S and R fits.
     Outputs data/p1v4/runs/grounding/control/control_readouts_start{s}.npz (same format as control_readouts.npz)
     and control_starts_fit_log.json.
dev: G2b (2b states minus control) and the ladder's presence rung (step 2 states minus control), with the identity
     change on that rung, under the three-way cluster bootstrap of scripts/p1v4_grounding_report.py; the control is
     taken per group as the mean over the 8 starts (each start's group concordance, averaged over starts, then over
     the six matched conditions as in the report); the stored single control alongside; each start's natural dev
     operating point (thresholds chosen as scripts/p1v4_grounding_report.py thresholds does for the control).
     Output results/main_v04/control_starts_dev.json.
Dev/train only; no test, no replication, no API.
usage (repo root): .venv-gpu/Scripts/python.exe -X utf8 scripts/p1v4_control_starts.py fit|dev
"""
import json
import os
import sys
import time

import numpy as np

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import p1v4_data as D  # noqa: E402
import p1v4_grounding as G  # noqa: E402
import p1v4_readout as RO  # noqa: E402

STARTS = tuple(range(8))
CDIR = f"{G.R}/grounding/control"


def start_path(s):
    return f"{CDIR}/control_readouts_start{s}.npz"


def load_start(s):
    z = np.load(start_path(s))
    out = {}
    for k in z.files:
        st, q, f = k.split("|")
        out.setdefault((st, q), {})[f] = z[k]
    return out


def fit_cmd():
    import torch
    D.gpu_guard()
    t0 = time.time()
    z = dict(np.load(f"{CDIR}/feats_train_natural.npz"))
    units = z["units"][z["q_win"]]
    rng = np.random.default_rng(RO.SEED)
    uniq = np.unique(z["units"])
    hold_units = set(rng.choice(uniq, size=len(uniq) // 5, replace=False))
    hold = np.array([u in hold_units for u in units])
    X = z["states"].astype(np.float32)
    stored = G.load_control()
    log = {}
    for s in STARTS:
        torch.manual_seed(s)
        models = {}
        for q in ("S", "R"):
            m = (z["q_task"] == q) & (z["q_gold"] >= 0)
            mu, sd = X[m].mean(0), X[m].std(0) + 1e-6
            assert np.abs(mu - stored[("states", q)]["mu"]).max() < 1e-4
            Xs = ((X - mu) / sd).astype(np.float32)
            y = z["q_gold"]
            best = None
            for wd in RO.WDS:
                lin = RO.train_logreg(Xs[m & ~hold], y[m & ~hold], wd)
                p = np.clip(RO.predict(lin, Xs[m & hold]), 1e-7, 1 - 1e-7)
                yy = y[m & hold]
                ll = float(-np.mean(yy * np.log(p) + (1 - yy) * np.log(1 - p)))
                log[f"start {s} states {q} wd {wd}"] = ll
                if best is None or ll < best[0]:
                    best = (ll, wd)
            lin = RO.train_logreg(Xs[m], y[m], best[1])
            models[f"states|{q}"] = {"mu": mu, "sd": sd, "w": lin.weight.detach().cpu().numpy()[0],
                                     "b": float(lin.bias.detach().cpu().numpy()[0]), "wd": best[1]}
            del Xs
        np.savez(start_path(s), **{f"{k}|{f}": v for k, dd in models.items() for f, v in dd.items()})
        print(f"start {s}: wd S {models['states|S']['wd']}, R {models['states|R']['wd']} "
              f"({time.time() - t0:.0f} s)", flush=True)
    json.dump(log, open(f"{CDIR}/control_starts_fit_log.json", "w"), indent=1)


def dev_cmd():
    import p1v4_grounding_report as GR
    import p1v4_readout_allclass as AC
    import p1v4_score as S
    rows, rows_by = G.load("dev")
    groups = G.load_groups("dev")
    units = [g["unit"] for g in groups if g["part"] == "r_hear"]
    cl = GR.cluster_table(rows, "dev")
    zn = dict(np.load(f"{RO.OUT}/feats_dev_natural.npz"))
    th_all = GR.thresholds(rows)
    ro = {"stored control": G.load_control(), "step 2 states": RO.load_readouts(), "2b states": AC.load_allclass()}
    th = {"stored control": th_all["control"], "step 2 states": th_all["states read-out"]}
    nat = json.load(open("results/main_v04/readout_allclass_dev.json"))["natural"]["all-class states"]["th"]
    th["2b states"] = (nat["S"], nat["R"])
    natural_op = {}
    for s in STARTS:
        ro[f"start {s}"] = load_start(s)
        op = S.operating_point(rows, RO.scores_of(zn, "states", ro[f"start {s}"]))
        th[f"start {s}"] = (op["th_s"], op["th_r"])
        natural_op[f"start {s}"] = {k: op[k] for k in ("primary", "floors_met", "lowest_floor", "th_s", "th_r")}
    ev, dp = {}, {}
    rh = [g for g in groups if g["part"] == "r_hear"]
    for cond in G.MATCHED:
        z = dict(np.load(f"{G.out_dir('dev')}/l1_{cond}.npz"))
        for name, r in ro.items():
            sc = RO.scores_of(z, "states", r)
            ev[(name, cond)] = GR.group_eval(groups, rows_by, S.decide(sc, *th[name]), sc)
            if cond != "none":
                dp.setdefault(name, []).append(np.mean([sc[(g["unit"], "1", g["k"])]["R"] - sc[(g["unit"], "2", g["k"])]["R"]
                                                        for g in rh]))

    def per_unit(name, field, v=None):
        return np.array([np.mean([(ev[(name, c)][u]["pair"][v] if v else ev[(name, c)][u][field])
                                  for c in G.MATCHED]) for u in units])

    starts = [f"start {s}" for s in STARTS]
    ctl = {"conc": np.mean([per_unit(n, "conc") for n in starts], 0),
           "2": np.mean([per_unit(n, None, "2") for n in starts], 0),
           "3": np.mean([per_unit(n, None, "3") for n in starts], 0)}
    one = {"conc": per_unit("stored control", "conc"), "2": per_unit("stored control", None, "2"),
           "3": per_unit("stored control", None, "3")}

    def crit(a, b, specificity=False):
        c = GR.criterion(units, cl, {}, lambda w: GR.wmean(w, a) - GR.wmean(w, b), lambda: float(a.mean() - b.mean()))
        if specificity:   # amendment 3.3: on the presence rung, identity must not rise by 0.20 or more
            c["rise_below_0.20"] = c["point"] < GR.G_MARGIN
        else:
            c["pass"] = c["point"] >= GR.G_MARGIN and c["ci95"][0] > 0
        return c

    res = {"n_groups": len(units), "natural_dev_operating_point": natural_op,
           "control_mean_of_8_starts": {"conc": float(ctl["conc"].mean()), "presence": float(ctl["2"].mean()),
                                        "identity": float(ctl["3"].mean())},
           "control_each_start": {n: {"conc": float(per_unit(n, "conc").mean()),
                                      "presence": float(per_unit(n, None, "2").mean()),
                                      "identity": float(per_unit(n, None, "3").mean()),
                                      "p_respond_1_minus_2_labelled": float(np.mean(dp[n]))} for n in starts},
           "stored_control": {"conc": float(one["conc"].mean()), "presence": float(one["2"].mean()),
                              "identity": float(one["3"].mean()),
                              "p_respond_1_minus_2_labelled": float(np.mean(dp["stored control"]))},
           "p_respond_1_minus_2_labelled": {n: float(np.mean(v)) for n, v in dp.items()},
           "criteria": {}}
    s2b, st2 = per_unit("2b states", "conc"), {v: per_unit("step 2 states", None, v) for v in ("2", "3")}
    for label, c in (("8-start mean", ctl), ("stored single", one)):
        res["criteria"][f"G2b: 2b states - control ({label})"] = crit(s2b, c["conc"])
        res["criteria"][f"presence rung: step 2 states - control ({label})"] = crit(st2["2"], c["2"])
        res["criteria"][f"identity change on the presence rung: step 2 states - control ({label})"] = crit(
            st2["3"], c["3"], specificity=True)
    json.dump(res, open("results/main_v04/control_starts_dev.json", "w"), indent=1)
    for n, v in natural_op.items():
        e = res["control_each_start"][n]
        print(f"{n}: natural dev five-part mean {v['primary']:.3f}, floors met {v['floors_met']}, "
              f"R-hear presence {e['presence']:.3f}, identity {e['identity']:.3f}, "
              f"P(respond) v1-v2 {e['p_respond_1_minus_2_labelled']:+.4f}")
    print("control, mean of 8 starts:", {k: round(v, 3) for k, v in res["control_mean_of_8_starts"].items()},
          "| stored single:", {k: round(v, 4) for k, v in res["stored_control"].items()})
    print("P(respond) v1-v2, labelled conditions:", {k: round(v, 3) for k, v in res["p_respond_1_minus_2_labelled"].items()
                                                     if not k.startswith("start")})
    for k, c in res["criteria"].items():
        flag = f"pass={c['pass']}" if "pass" in c else f"rise below 0.20={c['rise_below_0.20']}"
        print(f"{k}: {c['point']:+.3f} [{c['ci95'][0]:+.3f}, {c['ci95'][1]:+.3f}] {flag}")


if __name__ == "__main__":
    {"fit": fit_cmd, "dev": dev_cmd}[sys.argv[1]]()
